const ANDAMAN_LOCATIONS=[{name:"Natural Bridge (Howrah Bridge)",lat:11.8494,lng:93.0345,description:"A naturally formed rock arch carved by wave and coral erosion, at the edge of Laxmanpur Beach. Best seen at low tide."},{name:"Bharatpur Beach",lat:11.8347,lng:93.0384,description:"A calm bay near the jetty, popular for glass-bottom boat rides and shallow-water snorkelling over coral beds."},{name:"Laxmanpur Beach",lat:11.8452,lng:93.0169,description:"A long, west-facing stretch of white sand, home to the Natural Bridge and one of the island's best sunset spots."},{name:"Sitapur Beach (Sunrise Point)",lat:11.8223,lng:93.0432,description:"A quieter, rockier cove on the island's southeastern tip, known for sunrise views."},{name:"Neil Kendra (Jetty & Market)",lat:11.8358,lng:93.0298,description:"The island's small main village, ferry jetty and market — the starting point for exploring the rest of Neil Island."}],ANDAMAN_GALLERY=[{src:"../../assets/travel_beaches.png",caption:"Bharatpur Beach, Shaheed Dweep"},{src:"../../assets/travel_islands.png",caption:"The Natural Bridge at Laxmanpur Beach"},{src:"../../assets/travel_hidden.png",caption:"Coral beds visible from a glass-bottom boat"},{src:"../../assets/travel_mountains.png",caption:"Sunset over Laxmanpur Beach"}],ANDAMAN_FACTS=["Neil Island was officially renamed Shaheed Dweep ('Martyrs' Island') in 2018, in the same announcement that renamed Ross Island and Havelock Island.","The Natural Bridge, nicknamed 'Howrah Bridge' after its namesake in Kolkata, was formed entirely by decades of wave and coral erosion — no human hands involved.","Neil Island is often called the 'vegetable bowl' of the Andaman & Nicobar Islands, supplying much of the fresh produce sold in Port Blair's markets.","Many of the island's farming families are descendants of Bengali and Bihari settlers relocated here after Partition in the 1950s.","At just under 19 square kilometres, Shaheed Dweep is small enough to circle almost entirely by bicycle in a single day.","Sitapur Beach on the island's southeastern tip is nicknamed 'Sunrise Point,' facing the opposite direction from Laxmanpur's sunset views.","Bharatpur Beach's shallow, calm waters make it one of the most beginner-friendly snorkelling spots in the entire Andaman archipelago."];let map,currentGalleryIndex=0,factIndex=0;function initTabs(){const e=document.querySelectorAll(".andaman-tab-btn"),t=document.querySelectorAll(".andaman-tab-panel");e.forEach(a=>{a.addEventListener("click",()=>{const n=a.getAttribute("data-tab");e.forEach(e=>e.classList.remove("active")),a.classList.add("active"),t.forEach(e=>{e.classList.toggle("active",e.id==="tab-"+n)})})})}function initGallery(){const e=document.getElementById("andaman-gallery-grid");e&&(e.innerHTML="",ANDAMAN_GALLERY.forEach((t,a)=>{const n=document.createElement("figure");n.className="andaman-gallery-item",n.innerHTML=`\n      <img src="${t.src}" alt="${t.caption}" loading="lazy">\n      <figcaption>${t.caption}</figcaption>\n    `,n.addEventListener("click",()=>openLightbox(a)),e.appendChild(n)}))}function initLightbox(){document.querySelectorAll("[data-close-lightbox]").forEach(e=>{e.addEventListener("click",closeLightbox)});const e=document.getElementById("andaman-lightbox-prev"),t=document.getElementById("andaman-lightbox-next");e&&e.addEventListener("click",()=>showGalleryImage(currentGalleryIndex-1)),t&&t.addEventListener("click",()=>showGalleryImage(currentGalleryIndex+1)),document.addEventListener("keydown",e=>{const t=document.getElementById("andaman-lightbox");t&&!t.hidden&&("Escape"===e.key&&closeLightbox(),"ArrowRight"===e.key&&showGalleryImage(currentGalleryIndex+1),"ArrowLeft"===e.key&&showGalleryImage(currentGalleryIndex-1))})}function openLightbox(e){const t=document.getElementById("andaman-lightbox");t&&(t.hidden=!1,document.body.style.overflow="hidden",showGalleryImage(e))}function closeLightbox(){const e=document.getElementById("andaman-lightbox");e&&(e.hidden=!0,document.body.style.overflow="")}function showGalleryImage(e){const t=ANDAMAN_GALLERY.length;currentGalleryIndex=(e+t)%t;const a=ANDAMAN_GALLERY[currentGalleryIndex],n=document.getElementById("andaman-lightbox-image"),o=document.getElementById("andaman-lightbox-caption");n&&(n.src=a.src),n&&(n.alt=a.caption),o&&(o.textContent=a.caption)}function initFactsRotator(){const e=document.getElementById("andaman-fact-text"),t=document.getElementById("andaman-fact-dots");function a(a){factIndex=a,e.style.opacity="0",setTimeout(()=>{e.textContent=ANDAMAN_FACTS[factIndex],e.style.opacity="1"},200),t&&[...t.children].forEach((e,t)=>e.classList.toggle("active",t===factIndex))}e&&(t&&ANDAMAN_FACTS.forEach((e,n)=>{const o=document.createElement("button");o.className="andaman-fact-dot"+(0===n?" active":""),o.setAttribute("aria-label","Show fact "+(n+1)),o.addEventListener("click",()=>a(n)),t.appendChild(o)}),a(0),setInterval(()=>a((factIndex+1)%ANDAMAN_FACTS.length),6e3))}function initMap(){document.getElementById("andaman-map")&&"undefined"!=typeof L&&(map=L.map("andaman-map",{scrollWheelZoom:!1,minZoom:8}).setView([11.835,93.03],13),L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{attribution:"&copy; OpenStreetMap contributors &copy; CARTO",maxZoom:18}).addTo(map),ANDAMAN_LOCATIONS.forEach(e=>{L.circleMarker([e.lat,e.lng],{radius:8,color:"#ff9933",fillColor:"#ffb01f",fillOpacity:.85,weight:2}).addTo(map).bindPopup(`<strong>${e.name}</strong><br>${e.description}`)}))}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initGallery(),initFactsRotator(),initMap(),initLightbox()});